def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    initial_bins = bins + item  # approximating original capacity base for ratio
    fill_ratio = item / np.where(bins > 0, bins, 1.0)
    return np.where(remaining >= 0, -fill_ratio - (remaining / np.maximum(bins, 1e-5)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    with np.errstate(divide='ignore', invalid='ignore'):
        post_fill = item / np.maximum(bins, 1e-5)
        score = -np.exp(-remaining) - (1.0 / np.where(post_fill > 0, post_fill, 1e-5))
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    used = bins - remaining
    target = bins * 0.8
    penalty = -np.abs(used - target)
    return np.where(remaining >= 0, penalty, -np.inf)
